struct po {
    float data[16];
} __attribute__((aligned(16)));

struct frame_info {
    float age;
    int ifl_frame_boost;
    int ifl_frame_locked;
};

struct vector3d {
    float x;
    float y;
    float z;
};

struct instance_render_info {
    float number_of_faces_to_attempt;
    po local_to_world;
    unsigned int force_flags;
    unsigned int color_scale;
    float camera_relative_rotation;
    frame_info frame_time_info;
    void *my_region;
    float particle_scale;
    void *my_light_set;
    void *alt_materials;
    int frame;
    vector3d render_scale;
};

extern "C" void unguarded_linear_insert(
    instance_render_info *,
    instance_render_info
) __asm__("__unguarded_linear_insert__H2ZP20instance_render_infoZ20instance_render_info_X01X11_v");

__asm__(".equ __unguarded_linear_insert__H2ZP20instance_render_infoZ20instance_render_info_X01X11_v,0x002F2D38");

extern "C" void unguarded_insertion_sort_aux(
    instance_render_info *,
    instance_render_info *,
    instance_render_info *
) __asm__("__unguarded_insertion_sort_aux__H2ZP20instance_render_infoZ20instance_render_info_X01X01PX11_v");

void unguarded_insertion_sort_aux(
    instance_render_info *first,
    instance_render_info *last,
    instance_render_info *
) {
    for (instance_render_info *i = first; i != last; ++i)
        unguarded_linear_insert(i, instance_render_info(*i));
}
